package com.movieworth.api.movie;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="movies") public class Movie { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="tmdb_id",unique=true) Long tmdbId; @Column(nullable=false) String title; @Column(name="original_title") String originalTitle; String language; @Column(name="release_date") LocalDate releaseDate; @Column(name="poster_path") String posterPath; @Column(columnDefinition="text") String overview; Double popularity; @Column(name="created_at") OffsetDateTime createdAt; @Column(name="updated_at") OffsetDateTime updatedAt;
@PrePersist void create(){createdAt=updatedAt=OffsetDateTime.now();}@PreUpdate void update(){updatedAt=OffsetDateTime.now();}
public Long getId(){return id;}public Long getTmdbId(){return tmdbId;}public void setTmdbId(Long v){tmdbId=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getOriginalTitle(){return originalTitle;}public void setOriginalTitle(String v){originalTitle=v;}public String getLanguage(){return language;}public void setLanguage(String v){language=v;}public LocalDate getReleaseDate(){return releaseDate;}public void setReleaseDate(LocalDate v){releaseDate=v;}public String getPosterPath(){return posterPath;}public void setPosterPath(String v){posterPath=v;}public String getOverview(){return overview;}public void setOverview(String v){overview=v;}public Double getPopularity(){return popularity;}public void setPopularity(Double v){popularity=v;}}
